// Fully generated by AI

const MERCATOR_MAX = 20037508.34;

const lngLatToMercator = (lng, lat) => {
  const x = (lng * MERCATOR_MAX) / 180;
  const y =
    (Math.log(Math.tan(((90 + lat) * Math.PI) / 360)) / (Math.PI / 180)) *
    (MERCATOR_MAX / 180);
  return [x, y];
};

const substituteTemplateParams = (template, params = {}) => {
  let url = template;
  Object.keys(params).forEach((k) => {
    const value = params[k] == null ? "" : String(params[k]);
    url = url.replace(new RegExp(`\\{${k}\\}`, "g"), encodeURIComponent(value));
  });
  return url;
};

const findKeyCI = (map, name) => {
  const lower = name.toLowerCase();
  for (const k of map.keys()) {
    if (k.toLowerCase() === lower) return k;
  }
  return null;
};

export const buildGetFeatureInfoUrl = ({ layer, map, lngLat }) => {
  const template = layer?.layerConfig?.source?.tiles?.[0];
  if (!template || !map || !lngLat) return null;

  let url = substituteTemplateParams(template, layer.params);

  const size = 101;
  const half = Math.floor(size / 2);
  const pt = map.project(lngLat);
  const sw = map.unproject([pt.x - half, pt.y + half]);
  const ne = map.unproject([pt.x + half, pt.y - half]);
  const [minx, miny] = lngLatToMercator(sw.lng, sw.lat);
  const [maxx, maxy] = lngLatToMercator(ne.lng, ne.lat);
  url = url.replace("{bbox-epsg-3857}", `${minx},${miny},${maxx},${maxy}`);

  const [base, query = ""] = url.split("?");
  const params = new Map();
  query
    .split("&")
    .filter(Boolean)
    .forEach((pair) => {
      const [k, v = ""] = pair.split("=");
      params.set(k, v);
    });

  const versionKey = findKeyCI(params, "VERSION");
  const version = (versionKey && params.get(versionKey)) || "1.1.1";
  const layersKey = findKeyCI(params, "LAYERS");
  const layersVal = layersKey ? params.get(layersKey) : "";
  const crsKey = findKeyCI(params, "CRS") || findKeyCI(params, "SRS");
  const is13 = version.startsWith("1.3");

  params.set(findKeyCI(params, "REQUEST") || "REQUEST", "GetFeatureInfo");
  params.set(findKeyCI(params, "WIDTH") || "WIDTH", String(size));
  params.set(findKeyCI(params, "HEIGHT") || "HEIGHT", String(size));
  params.set("QUERY_LAYERS", layersVal);
  params.set("INFO_FORMAT", "application/json");
  params.set("FEATURE_COUNT", "10");

  if (!crsKey) {
    params.set(is13 ? "CRS" : "SRS", "EPSG:3857");
  }

  if (is13) {
    params.set("I", String(half));
    params.set("J", String(half));
  } else {
    params.set("X", String(half));
    params.set("Y", String(half));
  }

  const newQuery = Array.from(params.entries())
    .map(([k, v]) => `${k}=${v}`)
    .join("&");

  return `${base}?${newQuery}`;
};

export const fetchGetFeatureInfo = async ({ layer, map, lngLat }) => {
  const url = buildGetFeatureInfoUrl({ layer, map, lngLat });
  if (!url) return [];

  const res = await fetch(url);
  if (!res.ok) {
    throw new Error(`GetFeatureInfo failed (${res.status})`);
  }

  const contentType = res.headers.get("content-type") || "";
  if (!contentType.includes("json")) {
    // some servers return text/xml on error even when asked for json
    return [];
  }

  const json = await res.json();
  const features = Array.isArray(json?.features) ? json.features : [];
  return features.map((f) => ({
    properties: f?.properties || {},
    geometry: f?.geometry || null,
  }));
};
